// ⚙️ ZENTRALE KONFIGURATION – Gerätetopics
// Quelle sind die Tab-Env-Variablen (Tab oben rechts → „Env“):
//   WARP_DEV   = Topic-Präfix der WARP-Wallbox, z.B. "warp3/AbCd"
//   HASP_PLATE = Platten-Name der Anzeige  →  Topic hasp/<Plate>/...
// Die mqtt-in-Knoten abonnieren nichts statisch, sondern bekommen ihre Abos
// vom Folgeknoten „MQTT-Abos aus Konfiguration“ – hier ändert sich also NUR die Env.
global.set("warpDev", env.get("WARP_DEV") || "warp3/AbCd");
global.set("haspPlate", env.get("HASP_PLATE") || "openhasp");
return msg;

// 📡 MQTT-ABOS aus der Konfiguration – keine Topics in den mqtt-Knoten pflegen
// Quelle: Tab-Env (WARP_DEV / HASP_PLATE), gesetzt vom Knoten „Konfiguration (WARP/OpenHASP)“.
// Beide mqtt-in-Knoten laufen im Modus „Dynamic Subscription“ (inputs: 1) und
// bekommen ihre Abos von hier – ein Plattenwechsel ist damit NUR eine Env-Änderung.
var warpDev   = global.get("warpDev")   || "warp3/AbCd";
var haspPlate = global.get("haspPlate") || "openhasp";

// Ausgabe 1 → warp-in: alle Topics der Wallbox (Ausgabe evse/…/info/…/power_manager/…)
var warp = { action: "subscribe", topic: { topic: warpDev + "/#", qos: 1 } };

// Ausgabe 2 → hasp-in: NUR die Zustände, die der plate-router verarbeitet
// (kein „#“-Abo). Erweitern → hier UND im plate-router (case "pXbYY") ergänzen.
var stateObjs = ["p1b42", "p1b78", "p2b31", "p2b32"];
var haspSubs = stateObjs.map(function (obj) {
    return { topic: "hasp/" + haspPlate + "/state/" + obj, qos: 1 };
});
var hasp = { action: "subscribe", topic: haspSubs };

return [[warp], [hasp]];

initialize:
// On Start: Abos sofort anmelden, falls dieser Knoten neu startet
// (gleiche Logik wie im Hauptteil – bei Änderungen beide Blöcke anpassen)
var warpDev   = global.get("warpDev")   || "warp3/AbCd";
var haspPlate = global.get("haspPlate") || "openhasp";
var objs = ["p1b42", "p1b78", "p2b31", "p2b32"];
return [[{ action: "subscribe", topic: { topic: warpDev + "/#", qos: 1 } }],
        [{ action: "subscribe", topic: objs.map(function (obj) {
            return { topic: "hasp/" + haspPlate + "/state/" + obj, qos: 1 };
        }) }]];

func:
var t = msg.topic || "";
var W = (global.get("warpDev") || "warp3/AbCd") + "/";
var out = -1;
if (t === W + "power_manager/charge_mode") out = 0;
else if (t === W + "evse/state") out = 1;
else if (/\/meters\/\d+\/values$/.test(t)) out = 2;
else if (/\/meters\/\d+\/value_ids$/.test(t)) out = 3;
else if (t === W + "evse/hardware_configuration") out = 4;
else if (t === W + "evse/phases_connected") out = 5;
else if (/\/meters\/\d+\/config$/.test(t)) out = 6;
else if (t === W + "mqtt/state") out = 7;
else if (t === W + "evse/low_level_state") out = 8;
else if (t === W + "solar_forecast/state") out = 9;
else if (t === W + "evse/management_current") out = 10;
else if (t === W + "evse/external_current") out = 11;
else if (t === W + "evse/automation_current") out = 14;
else if (t === W + "info/name") out = 12;
else if (t === W + "info/display_name") out = 13;
if (out < 0) return null;
flow.set("lastWarp", Date.now());
var result = [null, null, null, null, null, null, null, null, null, null, null, null, null, null, null];
result[out] = msg;
return result;

var m = Number(msg.payload && msg.payload.mode);
var idx = (m === 1) ? 0 : (m === 2) ? 1 : (m === 3) ? 2 : 3;
msg.payload = idx;
msg.topic = "hasp/" + (global.get("haspPlate") || "openhasp") + "/command/p1b42.val";
return msg;

var H = (global.get("haspPlate") || "openhasp");
var s = msg.payload;
if (typeof s === "string") { try { s = JSON.parse(s); } catch (e) { return null; } }
if (!s || typeof s !== "object") return null;
flow.set("lastWarp", Date.now());
flow.set("warpState", s);   // letzter evse/state (für Phasen-Anzeige: lädt vs. idle)

function txt(id, payload) { return { topic: "hasp/" + H + "/command/" + id + ".text", payload: String(payload) }; }


var cs = s.charger_state;
var plain  = ["getrennt", "warten", "ladebereit", "lädt", "Fehler"][cs] || "?";
var marked = ["getrennt", "warten", "ladebereit", "#009000 lädt#", "#900000 Fehler#"][cs] || "?";

var iec = ["A – nicht verbunden", "B – verbunden", "C – lädt", "D – lädt (Belüftung)", "E/F – Fehler"][s.iec61851_state] || "?";
var cont = s.contactor_state;
var contText = (cont === 3) ? "geschlossen" : (cont === 1 || cont === 2) ? "nicht geschlossen" : "inaktiv";
var err = s.error_state;
var errText = (err === 0 || err === undefined) ? "kein Fehler"
    : ["", "", "Schalterfehler", "DC-Fehlerstrom", "Schützfehler", "Kommunikationsfehler"][err] || ("Fehler " + err);
var errDisp = (err === 0 || err === undefined) ? "kein Fehler" : ("#900000 " + errText + "#");

var allowed = s.allowed_charging_current || 0;
var freigabe = (allowed > 0) ? "ja" : "nein";
// Phasen: live (phases_current, evse/low_level_state) → Konfig (phases_connected) → Kontaktor-Fallback
var phasen = flow.get("phasenLive");
if (phasen !== 1 && phasen !== 3) phasen = flow.get("phasen");
if (phasen !== 1 && phasen !== 3) phasen = (s.contactor_state & 16) ? 3 : 1;
var phasenText = (phasen === 3) ? "3-phasig" : "1-phasig";
// Leistung: Slot 0 vorhanden (meterW_0 gesetzt) -> dessen Leistung anzeigen (auch 0),
// sonst die bereitgestellte Leistung: Spannung (230 V) x Ladestrom x Phasen.
// Anzeige in beiden Fällen gerundet auf 0,1 kW.
var actW = flow.get("meterW_0");
var kwText;
if (typeof actW === "number" && isFinite(actW)) {
    kwText = (actW / 1000).toFixed(1).replace(".", ",") + " kW";
} else {
    var kw = (allowed * 230 * phasen) / 1000000;
    kwText = kw.toFixed(1).replace(".", ",") + " kW";
}
var aText = (allowed / 1000).toFixed(0) + " A";

// Ladestatus-Footer (p1b13): ohne „Freigabe“
var sub = (freigabe === "ja") ? (aText + " · " + phasenText) : "kein Ladestrom";

// Sidebar-Lade-Icon (p0b90): Auto-Symbol E10B — Farbe je nach Ladestatus, „getrennt“ = unsichtbar
var iconColor = ["#9ca3af", "#ffd75e", "#62ddf5", "#6ab190", "#cc0000"][cs] || "#9ca3af";
var iconVis = (cs !== 0);

return [
    txt("p1b12", marked),
    txt("p1b13", sub),
    txt("p1b22", kwText),
    txt("p3b11", iec),
    txt("p3b12", plain),
    txt("p3b13", contText),
    txt("p3b14", errDisp),
    txt("p3b15", freigabe),
    { topic: "hasp/" + H + "/command/p0b90.text_color", payload: iconColor },
    { topic: "hasp/" + H + "/command/p0b90.vis", payload: String(iconVis) }
];

var H = (global.get("haspPlate") || "openhasp");
var vals = msg.payload;
if (!Array.isArray(vals)) return null;
var parts = String(msg.topic || "").split("/");
var slot = parseInt(parts[parts.length - 2], 10);
if (!isFinite(slot) || slot < 0 || slot > 4) return null;
var map = flow.get("mvids_" + slot);
if (!map) return null;
function g(id) {
    var i = map[id];
    if (i === undefined || i === null) return null;
    var v = vals[i];
    return (typeof v === "number" && isFinite(v)) ? v : null;
}
function fmt(v, unit, dec) {
    if (v === null || v === undefined) return "--";
    var neg = v < 0;
    var p = Math.abs(v).toFixed(dec).split(".");
    p[0] = p[0].replace(/\B(?=(\d{3})+(?!\d))/g, " ");
    return (neg ? "-" : "") + p.join(",") + " " + unit;
}
function txt(id, payload) { return { topic: "hasp/" + H + "/command/" + id + ".text", payload: String(payload) }; }
function col(id, payload) { return { topic: "hasp/" + H + "/command/" + id + ".bg_color", payload: String(payload) }; }

// Leistung: AC-Summe (74) → DC (404) → DC Laden/Entladen (403)
var w = g(74); if (w === null) w = g(404); if (w === null) w = g(403);
// tatsaechliche Leistung in Watt je Zaehler-Slot fuer die Leistungs-Anzeige (p1b22) vorhalten
flow.set("meterW_" + slot, (typeof w === "number" && isFinite(w)) ? w : null);
var pow = (w === null) ? "--" : (Math.abs(w) >= 1000) ? fmt(w / 1000, "kW", 2) : fmt(w, "W", 0);

// Ladestand (nur DC-Reporting / EV-fähige Zähler)
var soc = g(387);
var socText = (soc === null) ? "--" : fmt(soc, "%", 0);

// Phasen: Spannung > 180 V → c (verbunden), Strom > 0,3 A → a (aktiv), sonst d (ohne)
var state = ["?", "?", "?"];
var vols = [g(1), g(2), g(3)];
var imports = [g(11), g(15), g(19)];
var exports = [g(12), g(16), g(20)];
var sums    = [g(13), g(17), g(21)];
var diffs   = [g(14), g(18), g(22)];
var i;
for (i = 0; i < 3; i++) {
    if (vols[i] !== null && vols[i] !== undefined) state[i] = (vols[i] > 180) ? "c" : "d";
    var cur = null;
    if (imports[i] !== null && imports[i] !== undefined) cur = imports[i];
    else if (exports[i] !== null && exports[i] !== undefined) cur = exports[i];
    else if (sums[i] !== null && sums[i] !== undefined) cur = sums[i];
    if (cur !== null && cur > 0.3) state[i] = "a";
    else if (diffs[i] !== null && diffs[i] !== undefined && Math.abs(diffs[i]) > 0.3) state[i] = "a";
}

var name = flow.get("meterName_" + slot) || ("Zähler #" + slot);
var PCOLORS = { "?": "#9ca3af", "d": "#9ca3af", "c": "#2563eb", "a": "#009000" };
var d = 180 + slot * 3;
return [
    txt("p4b" + (201 + slot), name),
    txt("p4b" + (211 + slot), pow),
    txt("p4b" + (221 + slot), socText),
    col("p4b" + d, PCOLORS[state[0]]),
    col("p4b" + (d + 1), PCOLORS[state[1]]),
    col("p4b" + (d + 2), PCOLORS[state[2]])
];

if (Array.isArray(msg.payload)) {
    var parts = String(msg.topic || "").split("/");
    var slot = parseInt(parts[parts.length - 2], 10);
    if (!isNaN(slot) && slot >= 0 && slot <= 4) {
        var map = {};
        msg.payload.forEach(function (v, i) { map[v] = i; });
        flow.set("mvids_" + slot, map);
    }
}
return null;

var obj = String(msg.topic || "").split("/").pop();
switch (obj) {
    case "p1b42": return [msg, null, null, null];
    case "p1b78": return [null, msg, null, null];
    case "p2b31": return [null, null, msg, null];
    case "p2b32": return [null, null, null, msg];
    default: return null;
}

var v = (msg.payload && msg.payload.val);
if (v === undefined || v === null) return null;
var modes = [1, 2, 3, 0];   // Aus→Off(1), Solar→PV(2), Minimum→Min+PV(3), Schnell→Fast(0)
var m = modes[Number(v)];
if (m === undefined) return null;
msg.payload = { mode: m };
msg.topic = (global.get("warpDev") || "warp3/AbCd") + "/power_manager/charge_mode_update";
return msg;

var raw;
if (msg.payload && typeof msg.payload === "object" && msg.payload.temperature !== undefined) raw = Number(msg.payload.temperature);
else raw = Number(msg.payload);
if (isNaN(raw)) return null;

var t = Math.round(raw / 100);

var H = global.get("haspPlate") || "openhasp";
msg.topic   = "hasp/" + H + "/command/p3b16.text";
msg.payload = t + "°C";
return msg;

var s = msg.payload;
if (typeof s === "string") { try { s = JSON.parse(s); } catch (e) { return null; } }
if (!s || typeof s !== "object" || typeof s.phases !== "number") return null;
if (s.phases !== 1 && s.phases !== 3) return null;
flow.set("phasen", s.phases);
var H = (global.get("haspPlate") || "openhasp");
var eff = flow.get("phasenLive");
if (eff !== 1 && eff !== 3) eff = flow.get("phasen");
var p1 = (eff === 1), p3 = (eff === 3);
var val = (p1) ? 0 : 1;
return [[
        { topic: "hasp/" + H + "/command/p1b78.val", payload: val },
        // Suffix-Semantik (Styling-Doku): 4X = Teil 4 (Buttons), 2. Ziffer = State.
        // 41 = toggled/gecheckt -> aktiver Knopf (folgt `val`), 40 = default (alle Knöpfe normal).
        { topic: "hasp/" + H + "/command/p1b78.bg_color40", payload: "#ffffff" },
        { topic: "hasp/" + H + "/command/p1b78.bg_grad_color40", payload: "#ffffff" },
        { topic: "hasp/" + H + "/command/p1b78.text_color40", payload: "#374151" },
        { topic: "hasp/" + H + "/command/p1b78.bg_color41", payload: "#0d6efd" },
        { topic: "hasp/" + H + "/command/p1b78.bg_grad_color41", payload: "#0d6efd" },
        { topic: "hasp/" + H + "/command/p1b78.text_color41", payload: "white" }
]];

var parts = String(msg.topic || "").split("/");
var slot = parseInt(parts[parts.length - 2], 10);
if (!isFinite(slot) || slot < 0 || slot > 4) return null;
var c = msg.payload;
if (typeof c === "string") { try { c = JSON.parse(c); } catch (e) { return null; } }
var name = null;
if (Array.isArray(c)) {
    if (c[1] && typeof c[1] === "object" && typeof c[1].display_name === "string") name = c[1].display_name;
} else if (c && typeof c === "object") {
    if (typeof c.display_name === "string") name = c.display_name;
    else if (c[1] && typeof c[1] === "object" && typeof c[1].display_name === "string") name = c[1].display_name;
}
if (name) flow.set("meterName_" + slot, name);
return null;

var s = msg.payload;
if (typeof s === "string") { try { s = JSON.parse(s); } catch (e) { return null; } }
if (!s || typeof s !== "object" || typeof s.connection_state !== "number") return null;
flow.set("warpConn", s.connection_state);
return null;

var s = msg.payload;
if (typeof s === "string") { try { s = JSON.parse(s); } catch (e) { return null; } }
if (!s || typeof s !== "object" || typeof s.phases_current !== "number") return null;
var H = (global.get("haspPlate") || "openhasp");
// Phasenanzeige: nur während des Ladens zählt die tatsächliche Phasenzahl
// (phases_current). Ohne aktive Ladung zeigt das Display "1-phasig" – auch wenn
// die Zuleitung 3-phasig ist und die Kontaktoren geschlossen bleiben.
var st = flow.get("warpState");
var ph = 1;   // Standard ohne Ladung: 1-phasig
if (st && st.charger_state === 3 && (s.phases_current === 1 || s.phases_current === 3)) {
    ph = s.phases_current;
}
flow.set("phasenLive", ph);
var p1 = (ph === 1), p3 = (ph === 3);
var val = (p1) ? 0 : 1;
return [[
        { topic: "hasp/" + H + "/command/p1b78.val", payload: val },
        // Suffix-Semantik (Styling-Doku): 4X = Teil 4 (Buttons), 2. Ziffer = State.
        // 41 = toggled/gecheckt -> aktiver Knopf (folgt `val`), 40 = default (alle Knöpfe normal).
        { topic: "hasp/" + H + "/command/p1b78.bg_color40", payload: "#ffffff" },
        { topic: "hasp/" + H + "/command/p1b78.bg_grad_color40", payload: "#ffffff" },
        { topic: "hasp/" + H + "/command/p1b78.text_color40", payload: "#374151" },
        { topic: "hasp/" + H + "/command/p1b78.bg_color41", payload: "#0d6efd" },
        { topic: "hasp/" + H + "/command/p1b78.bg_grad_color41", payload: "#0d6efd" },
        { topic: "hasp/" + H + "/command/p1b78.text_color41", payload: "white" }
]];

var v = Number(msg.payload && msg.payload.val);
if (v !== 0 && v !== 1) return null;   // btnmatrix: 0=1-phasig, 1=3-phasig; deselect/anderes ignorieren
var phases = (v === 1) ? 3 : 1;
msg.payload = { phases_wanted: phases };
msg.topic = (global.get("warpDev") || "warp3/AbCd") + "/power_manager/external_control_update";
return msg;

// Watchdog-Takt (15 s): gecachten evse/state erneut in die Anzeige geben,
// damit kW-/Phasen-/Statuswerte auch ohne State-Änderung (evse/state publiziert nur bei
// Änderung, retained) und nach Neustart aktuell bleiben. Nur bei bestätigter Verbindung
// (connection_state == 2), damit kein künstlich frisch gehaltener lastWarp-Zeitstempel
// den offline-Fallback (kein WARP-Frame > ~100 s) aushebelt.
var conn = flow.get("warpConn");
if (conn !== 2) return null;
var st = flow.get("warpState");
if (!st || typeof st !== "object") return null;
return { payload: st };

var H = (global.get("haspPlate") || "openhasp");
var s = msg.payload;
if (typeof s === "string") { try { s = JSON.parse(s); } catch (e) { return null; } }
if (!s || typeof s !== "object" || typeof s.current !== "number") return null;
var a = Math.round(s.current / 1000) + " A";
var col = (s.current > 0) ? "#111827" : "#9ca3af";
// Achtung: doppelte Klammer noetig! Ein Function-Knoten mit EINEM Ausgang
// verwirft bei "return [m1, m2, ...]" alle Nachrichten ausser der ersten
// (Array-Index = Ausgang, siehe Node.prototype.send in @node-red/runtime 4.0.2).
return [[
    { topic: "hasp/" + H + "/command/p2b27.text", payload: a },
    { topic: "hasp/" + H + "/command/p2b27.text_color", payload: col }
]];

var H = (global.get("haspPlate") || "openhasp");
var t = msg.topic || "";
var s = msg.payload;
if (typeof s === "string") { try { s = JSON.parse(s); } catch (e) { return null; } }
if (!s || typeof s !== "object" || typeof s.current !== "number") return null;
// Quelle merken und den jeweiligen Quellwert im Cache ablegen
if (/\/evse\/external_current$/.test(t)) flow.set("extCur", s.current);
else if (/\/evse\/automation_current$/.test(t)) flow.set("autoCur", s.current);
else return null;
// Effektiven Wert waehlen: der kleinere von beiden (falls beide bekannt), sonst der bekannte
var ext = flow.get("extCur"), auto = flow.get("autoCur"), eff;
if (typeof ext === "number" && typeof auto === "number") eff = Math.min(ext, auto);
else if (typeof ext === "number") eff = ext;
else eff = auto;
if (typeof eff !== "number") return null;
flow.set("effCur", eff);   // Basis fuer die ±1-A-Tasten = effektiver (kleinerer) Wert
var a = Math.round(eff / 1000) + " A";
var col = (eff > 0) ? "#111827" : "#9ca3af";
// Achtung: doppelte Klammer noetig! Ein Function-Knoten mit EINEM Ausgang
// verwirft bei "return [m1, m2, ...]" alle Nachrichten ausser der ersten
// (Array-Index = Ausgang, siehe Node.prototype.send in @node-red/runtime 4.0.2).
return [[
    { topic: "hasp/" + H + "/command/p2b23.text", payload: a },
    { topic: "hasp/" + H + "/command/p2b23.text_color", payload: col }
]];

if (!(msg.payload && msg.payload.event === "down")) return null;
var H = (global.get("haspPlate") || "openhasp");
var c = flow.get("effCur");
if (typeof c !== "number" || !isFinite(c)) c = 16000;   // noch kein Wert gesehen
c = Math.max(6000, c - 1000);
flow.set("effCur", c);
// Achtung: doppelte Klammer noetig! Ein Function-Knoten mit EINEM Ausgang
// verwirft bei "return [m1, m2, ...]" alle Nachrichten ausser der ersten
// (Array-Index = Ausgang, siehe Node.prototype.send in @node-red/runtime 4.0.2).
return [[
    { topic: (global.get("warpDev") || "warp3/AbCd") + "/evse/external_current", payload: { current: c } },
    { topic: (global.get("warpDev") || "warp3/AbCd") + "/evse/automation_current_update", payload: { current: c } },
    { topic: "hasp/" + H + "/command/p2b23.text", payload: Math.round(c / 1000) + " A" }
]];

if (!(msg.payload && msg.payload.event === "down")) return null;
var H = (global.get("haspPlate") || "openhasp");
var c = flow.get("effCur");
if (typeof c !== "number" || !isFinite(c)) c = 16000;   // noch kein Wert gesehen
c = Math.min(32000, c + 1000);
flow.set("effCur", c);
// Achtung: doppelte Klammer noetig! Ein Function-Knoten mit EINEM Ausgang
// verwirft bei "return [m1, m2, ...]" alle Nachrichten ausser der ersten
// (Array-Index = Ausgang, siehe Node.prototype.send in @node-red/runtime 4.0.2).
return [[
    { topic: (global.get("warpDev") || "warp3/AbCd") + "/evse/external_current", payload: { current: c } },
    { topic: (global.get("warpDev") || "warp3/AbCd") + "/evse/automation_current_update", payload: { current: c } },
    { topic: "hasp/" + H + "/command/p2b23.text", payload: Math.round(c / 1000) + " A" }
]];

// Jumper-/Schalter-Obergrenze der Zuleitung (evse/hardware_configuration) als
// Default des externen Slots (evse/external_defaults) vorbelegen: Nach einem
// Neustart des Charge-Controllers gilt dann die Hardware-Obergrenze.
// jumper_configuration: 0-6 -> 6..32 A; 7=Software; 8=nicht konfiguriert.
var s = msg.payload;
if (typeof s === "string") { try { s = JSON.parse(s); } catch (e) { return null; } }
if (!s || typeof s !== "object" || typeof s.jumper_configuration !== "number") return null;
var limit = [6000, 10000, 13000, 16000, 20000, 25000, 32000][s.jumper_configuration];
if (limit === undefined || limit === null) return null;   // Software/nicht konfiguriert -> nichts ändern
if (flow.get("extDefaultLim") === limit) return null;     // bereits gesetzt
flow.set("extDefaultLim", limit);
return {
    topic: (global.get("warpDev") || "warp3/AbCd") + "/evse/external_defaults_update",
    payload: { current: limit, clear_on_disconnect: false }
};

// solar_forecast/state.wh_today_remaining → Leistung (p1b23): "0,0 kWh" (bei 0 ausgeblendet via .vis)
var s = msg.payload;
if (typeof s === "string") { try { s = JSON.parse(s); } catch (e) { return null; } }
if (!s || typeof s.wh_today_remaining !== "number") return null;
var H = global.get("haspPlate") || "openhasp";
var vis = (s.wh_today_remaining !== 0);
var txt = vis ? "\uE599 " + (s.wh_today_remaining / 1000).toFixed(1).replace(".", ",") + " kWh" : "";  // Sonnen-Icon vor dem Wert
return [[
    { topic: "hasp/" + H + "/command/p1b23.text", payload: txt },
    { topic: "hasp/" + H + "/command/p1b23.vis", payload: String(vis) }
]];

// info/display_name (falls gesetzt) sonst info/name → Kopfzeile (p0b13, Titelzeile)
var s = msg.payload;
if (typeof s === "string") { try { s = JSON.parse(s); } catch (e) { return null; } }
if (!s || typeof s !== "object") return null;
if (/\/info\/display_name$/.test(msg.topic || "")) {
    // Anzeigename merken; leerer Wert = Löschen → Fallback auf Gerätename
    flow.set("dispName", (typeof s.display_name === "string") ? s.display_name.trim() : "");
} else if (typeof s.name === "string") {
    flow.set("devName", s.name);
}
var disp = flow.get("dispName");
var name = flow.get("devName");
var display = (disp && disp.length > 0) ? disp : name;
if (!display) return null;
msg.payload = display;
msg.topic = "hasp/" + (global.get("haspPlate") || "openhasp") + "/command/p0b13.text";
return msg;
